#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s! %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s-> opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Capture baseline policy-gate snapshots on a lab VM (issue #7).
# For each scenario with a ticket scope (src/policy/scopes/), we restore the
# seed snapshot, set up the trap, run W_prod with the injector, and collect
# both nodes with src/policy/capture-baseline.ts. Each snapshot is redacted,
# validated and written to src/policy/fixtures/baselines/<id>.json.
# Usage: scripts/capture-baselines.sh [scenario ...]   (default: every scope)
# Secrets: the Postgres password is asked for (hidden) only if the lab does
# not use the documented default. It is exported to the capture process and
# never written to .env, fixtures or logs.

run_wizard() {

cd "$(dirname "${BASH_SOURCE[0]}")/.."
export PATH="$HOME/.bun/bin:$PATH"
ENV_FILE=".env"
local CAPTURE=(bun run src/policy/capture-baseline.ts)
local BASELINES="src/policy/fixtures/baselines"
local REMOTE="/opt/pgaibench/env"
local SSH_OPTS=(-o BatchMode=yes -o ConnectTimeout=10 -o StrictHostKeyChecking=accept-new -o "UserKnownHostsFile=$HOME/.ssh/known_hosts_pgaibench")
local IDS=() CAPTURED=() FAILED=() MISSING=() FILES=() id plan out rc f IP

if (( $# )); then IDS=("$@"); else mapfile -t IDS < <("${CAPTURE[@]}" --list); fi

TOTAL_STAGES=$(( 4 + ${#IDS[@]} + 2 ))

banner "Baseline snapshots for policy replay (${#IDS[@]} scenarios)"

# ── Stage 1 ──────────────────────────────────────────────────────────────
stage "Pick the lab VM"
say "Each capture runs on one seed VM from env/hosts.json (see env/README.md)."
say "Stop batches and episodes on that VM first: every capture resets it."
if [[ ! -f env/hosts.json ]]; then
  warn "env/hosts.json is missing. Write it in the format of env/hosts.example.json, then re-run."
  exit 1
fi
command -v bun >/dev/null || { warn "bun is not on PATH"; exit 1; }
ask PGAIBENCH_BASELINE_SEED "Seed VM number (1, 2 or 3):"
[[ "$PGAIBENCH_BASELINE_SEED" =~ ^[1-9][0-9]*$ ]] || { warn "not a seed number"; exit 1; }
write_env PGAIBENCH_BASELINE_SEED "$PGAIBENCH_BASELINE_SEED"
IP=$(bun -e 'const h = JSON.parse(await Bun.file("env/hosts.json").text()).seeds?.[process.argv[1]]; if (!h?.ip) process.exit(1); console.log(h.ip)' "$PGAIBENCH_BASELINE_SEED") \
  || { warn "no host for seed $PGAIBENCH_BASELINE_SEED in env/hosts.json"; exit 1; }
if ssh "${SSH_OPTS[@]}" "root@$IP" true; then
  note "ssh to seed $PGAIBENCH_BASELINE_SEED works."
else
  warn "ssh to seed $PGAIBENCH_BASELINE_SEED failed; fix access and re-run."; exit 1
fi
pause

# ── Stage 2 ──────────────────────────────────────────────────────────────
stage "Copy env/ to the VM"
say "The VM must run this tree's scripts (reset.sh, scenario-setup.sh, w_prod.sh)."
say "We copy without --delete, so private setup files already on the VM stay."
if confirm "Copy env/ to $REMOTE on seed $PGAIBENCH_BASELINE_SEED now?"; then
  rsync -a --exclude hosts.json -e "ssh ${SSH_OPTS[*]}" env/ "root@$IP:$REMOTE/" && note "copied."
else
  note "skipped; the VM keeps its current env/."
fi
pause

# ── Stage 3 ──────────────────────────────────────────────────────────────
stage "Postgres password"
say "We use the lab default from env/README.md unless this lab changed it."
unset PGAIBENCH_PG_PASSWORD
if confirm "Does this lab use a non-default Postgres password?"; then
  ask_secret PGAIBENCH_PG_PASSWORD "Postgres password (hidden; not saved anywhere):"
  export PGAIBENCH_PG_PASSWORD
fi
pause

# ── Stage 4 ──────────────────────────────────────────────────────────────
stage "Private setup files for corpus scenarios"
say "Track 2 corpus scenarios outside the public set have no trap in the seed."
say "Their setup SQL is private and must be on the VM at $REMOTE/scenario-setup/<id>.sql."
for id in "${IDS[@]}"; do
  plan=$("${CAPTURE[@]}" --plan "$id")
  if [[ "$plan" == *'"requireSetup":true'* ]] && ! ssh "${SSH_OPTS[@]}" "root@$IP" test -f "$REMOTE/scenario-setup/$id.sql"; then
    MISSING+=("$id")
  fi
done
if (( ${#MISSING[@]} )); then
  warn "missing on the VM: ${MISSING[*]}"
  step "From the private tree, copy each one: scp <private>/scenario-setup/<id>.sql root@<vm>:$REMOTE/scenario-setup/"
  pause "Press Enter when copied (without them, those captures stop before the workload)"
else
  note "every corpus scenario has its setup file on the VM."
  pause
fi

# ── One stage per scenario ───────────────────────────────────────────────
for id in "${IDS[@]}"; do
  stage "Capture $id"
  if [[ -f "$BASELINES/$id.json" ]] && ! confirm "$BASELINES/$id.json exists. Capture it again?"; then
    note "kept the existing fixture."; continue
  fi
  say "reset.sh, trap setup, W_prod for 180 s, snapshot of both nodes at 120 s."
  say "About 4 minutes. Leave seed $PGAIBENCH_BASELINE_SEED alone meanwhile."
  while true; do
    rc=0
    out=$("${CAPTURE[@]}" --seed "$PGAIBENCH_BASELINE_SEED" --scenario "$id" 2>&1 | tee /dev/stderr) || rc=$?
    if (( rc == 0 )); then
      if [[ "$out" == *WARNING* ]]; then
        warn "the snapshot lacks some scope objects (above): the trap may not be set up."
        if ! confirm "Keep $BASELINES/$id.json anyway?"; then
          rm -f "$BASELINES/$id.json"; FAILED+=("$id"); break
        fi
      fi
      CAPTURED+=("$id"); break
    fi
    warn "capture of $id failed."
    note "If the error comes from docs/policy-gate/sql, fix the SQL, note what failed in its commit, and retry."
    confirm "Retry $id?" || { FAILED+=("$id"); break; }
  done
  pause
done

# ── Stage N+5 ────────────────────────────────────────────────────────────
stage "Reset the VM"
say "The last capture left its trap on seed $PGAIBENCH_BASELINE_SEED."
if confirm "Run reset.sh on seed $PGAIBENCH_BASELINE_SEED now?"; then
  ssh "${SSH_OPTS[@]}" "root@$IP" "$REMOTE/reset.sh" || warn "reset.sh failed; run it by hand before the next batch."
fi
pause

# ── Stage N+6 ────────────────────────────────────────────────────────────
stage "Validate and commit"
for id in "${CAPTURED[@]}"; do FILES+=("$BASELINES/$id.json"); done
for f in "${FILES[@]}"; do "${CAPTURE[@]}" --check "$f" || { warn "$f fails validation"; exit 1; }; done
bun test src/policy/capture-baseline.test.ts || { warn "baseline tests fail"; exit 1; }
(( ${#FAILED[@]} )) && SKIPPED+=("capture again: ${FAILED[*]}")
if (( ${#FILES[@]} )); then
  say "Captured: ${CAPTURED[*]}"
  if confirm "Commit these ${#FILES[@]} fixture(s) now?"; then
    git add -- "${FILES[@]}"
    git commit -m "Add baseline snapshots from seed $PGAIBENCH_BASELINE_SEED" -- "${FILES[@]}"
  else
    SKIPPED+=("commit: git add ${FILES[*]}")
  fi
else
  note "nothing new to commit."
fi

finish
}

run_wizard "$@"; exit
